import{_ as a,o as s,c as i,a5 as t}from"./chunks/framework.DrDMl0tG.js";const n="/assets/island_sleep_benchmark.DWHjJeYl.png",m=JSON.parse('{"title":"Benchmark Example: Island Sleep","description":"","frontmatter":{},"headers":[],"relativePath":"sections/examples/server/island_sleep_benchmark.md","filePath":"sections/examples/server/island_sleep_benchmark.md"}'),l={name:"sections/examples/server/island_sleep_benchmark.md"};function r(p,e,h,o,d,c){return s(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="benchmark-example-island-sleep" tabindex="-1">Benchmark Example: Island Sleep <a class="header-anchor" href="#benchmark-example-island-sleep" aria-label="Permalink to &quot;Benchmark Example: Island Sleep&quot;">​</a></h1><p><img src="'+n+`" alt="island_sleep_benchmark example"></p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Visualizes the sleeping-island system. A sleeping island is a connected group of bodies that has come to rest (low velocity and low contact activity). The simulator marks it as sleeping and skips its updates until something wakes it.</p><p>The scene builds four separate 3 × 3 × 3 box stacks (islands). Boxes turn blue while sleeping and red while active. At step 2500 (5 s), a heavy sphere is launched into one stack to wake that island.</p><h2 id="target" tabindex="-1">Target <a class="header-anchor" href="#target" aria-label="Permalink to &quot;Target&quot;">​</a></h2><p>CMake target: <code>island_sleep_benchmark</code>.</p><h2 id="run" tabindex="-1">Run <a class="header-anchor" href="#run" aria-label="Permalink to &quot;Run&quot;">​</a></h2><p>Start the viewer, then run the example on one thread:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Terminal 1</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./build-examples/examples/rayrai_tcp_viewer</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Terminal 2</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">OMP_NUM_THREADS</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> OPENBLAS_NUM_THREADS</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">1</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  ./build-examples/examples/island_sleep_benchmark</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --steps=12000</span></span></code></pre></div><p>On Windows, run <code>island_sleep_benchmark.exe</code> instead. This example uses RaisimServer on port 8080. When the run ends, it prints the number of steps and the achieved step rate. Each step also sleeps 2 ms so the run can be watched in real time, so the printed rate is not a raw solver throughput.</p><h2 id="arguments" tabindex="-1">Arguments <a class="header-anchor" href="#arguments" aria-label="Permalink to &quot;Arguments&quot;">​</a></h2><ul><li><code>--steps=N</code>: number of simulation steps to run (default: 12000).</li><li><code>--hit-step=N</code>: step at which to launch the wake sphere (default: 2500; clamped to the last step for shorter runs).</li></ul>`,13)])])}const u=a(l,[["render",r]]);export{m as __pageData,u as default};
